4249.sent:
let lookback = 7d;
ImWebSession
| where TimeGenerated > ago(lookback)
| where isnotempty(Url)
// url_decode normalises %29%29%20AS%20DECIMAL%29 style encoding back to the raw payload
| extend DecodedUrl = tolower(url_decode(Url))
// the Sequelize JSON-path cast-break the article shows: a')) AS DECIMAL) = 1 ...
| where DecodedUrl matches regex @"\)\s*\)\s*as\s+decimal\s*\)"
// require a SQLi follow-on token so a stray 'AS DECIMAL)' in legit traffic doesn't fire
| where DecodedUrl has "union" or DecodedUrl contains "version()" or DecodedUrl contains "drop table"
| project TimeGenerated, SrcIpAddr, HttpRequestHeaderUserAgent, HttpMethod, DstHostname, Url, DecodedUrl, HttpStatusCode, EventProduct
| order by TimeGenerated desc
